ls fixtures | head; python3 - <<'EOF'
import json,glob
for f in glob.glob('fixtures/**/*.json',recursive=True):
    try: d=json.load(open(f))
    except Exception: continue
    items = d.get('data') if isinstance(d,dict) else d
    if not isinstance(items,list): continue
    for p in items:
        if isinstance(p,dict) and p.get('id') in (118,'118'):
            print(f); print(json.dumps({k:p[k] for k in p if k not in('description','shortDescription','rawAttributes')},indent=1)[:3000])
EOF

