input.command:
python3 - <<'EOF'
import json
d=json.load(open('fixtures/catalog.json'))
print(type(d), list(d.keys())[:10] if isinstance(d,dict) else len(d))
def walk(o,path=''):
    if isinstance(o,dict):
        if o.get('id') in (118,'118') and 'price' in o:
            print(path); print(json.dumps({k:v for k,v in o.items() if k not in ('description','shortDescription')},indent=1)[:4000]); return True
        for k,v in o.items():
            if walk(v,path+'/'+k): return True
    elif isinstance(o,list):
        for i,v in enumerate(o):
            if walk(v,path+'[%d]'%i): return True
walk(d)
EOF

