input.command:
cd /Users/matteodospina/orca/workspaces/vela/task-selection-improvements/tests && uv run python3 - <<'EOF'
import subprocess,glob,os,sys
for f in sorted(glob.glob('test_*.py')):
    m=f[:-3]
    try:
        r=subprocess.run([sys.executable,'-m','unittest',m],capture_output=True,text=True,timeout=90)
        last=r.stderr.strip().splitlines()[-1]
        if not last.startswith('OK'): print(m, last, flush=True)
    except subprocess.TimeoutExpired:
        print(m,'TIMEOUT',flush=True)
EOF

